<?php
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['approval_id'])){$status=$_POST['decision']==='approve'?'Approved':'Rejected';$pdo->prepare("UPDATE approvals SET status=? WHERE id=?")->execute([$status,(int)$_POST['approval_id']]);header('Location:index.php?page=approval');exit;}
$rows=$pdo->query("SELECT * FROM approvals ORDER BY FIELD(status,'Pending','Rejected','Approved'),id DESC")->fetchAll();$pending=count(array_filter($rows,fn($r)=>$r['status']==='Pending'));
?><div class="page-head"><div><h1>Approval Center</h1><p>Approval queue untuk KAK, sourcing, change order, dan kontrak.</p></div><span class="approval-summary"><i class="bi bi-hourglass-split"></i> <?=$pending?> pending approval</span></div><div class="card p-3"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Reference</th><th>Type</th><th>Title</th><th>Requester</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=de($r['ref_no'])?></strong></td><td><?=de($r['ref_type'])?></td><td><?=de($r['title'])?></td><td><?=de($r['requester']?:'-')?></td><td><span class="status-pill <?=strtolower($r['status'])?>"><?=de($r['status'])?></span></td><td><?php if($r['status']==='Pending'):?><form method="post" class="d-flex gap-1"><input type="hidden" name="approval_id" value="<?=$r['id']?>"><button class="btn btn-sm btn-success" name="decision" value="approve"><i class="bi bi-check"></i></button><button class="btn btn-sm btn-outline-danger" name="decision" value="reject"><i class="bi bi-x"></i></button></form><?php else:?><span class="text-muted small">Completed</span><?php endif;?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="6" class="text-center text-muted py-5">Belum ada approval queue.</td></tr><?php endif;?></tbody></table></div></div>
